mod qualify;mod reference;mod packet;mod linear;mod producer;mod verifier;
mod core;mod certificate;
#[path="../triangular-witness/cost.rs"]mod cost;
#[path="../canonical-root/root.rs"]mod root;
#[path="../triangular-witness/geometry.rs"]mod geometry;
use hec_native_ic::{counted,fp::Fp,poly::Poly,jac::Curve,instance::factor_base,rng::Rng};use packet::Context;
fn emit(p:u64,sm:u64,case:usize,rep:usize,name:&str,counts:&counted::Counts){for(m,v)in counts{assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{case}\t{rep}\t{name}\t{m}\t{}",v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}}
fn add(a:&counted::Counts,b:&counted::Counts)->counted::Counts{let mut out=a.clone();for(m,v)in b{let w=out.entry(*m).or_default();for j in 0..16{w[j]+=v[j]}}out}
fn main(){counted::disable();geometry::controls();geometry::repeated_control();let prior:Vec<Vec<&str>>=include_str!("../triangular-witness/CONTROL.tsv").lines().skip(1).map(|l|l.split('\t').collect()).collect();let mut calls=0;println!("p\tsm\tcase\trep\tphase\tmodulus\tcounts");for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&c);let pt=fb[0];let base=c.place(pt.0,pt.1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let k=1+rng.below(ell-1);let target=c.mul(&d,k);let context=Context{c:c.clone(),d,target,ell,sm};let mut first=None;for rep in 0..2{counted::reset();let mut last=None;for seed in 1..=3{let tr=core::solve(&c,pt,&d,&target,ell,sm,seed,false,true);if tr.answer.is_some(){last=Some(tr);break}}let pc=counted::snapshot();counted::disable();let external=cost::snapshot();let tr=last.unwrap();assert_eq!(tr.answer.unwrap().1,k);if rep==0{let mut diagnostic=None;for seed in 1..=3{let q=core::solve(&c,pt,&d,&target,ell,sm,seed,true,true);if q.answer.is_some(){diagnostic=Some(q);break}}assert_eq!(tr,diagnostic.unwrap());}for(name,counts)in[("producer_with_native_control",&pc),("native_control",&external)]{for(m,v)in counts{if name=="producer_with_native_control"{continue}let row=prior.iter().find(|x|x[0]==p.to_string()&&x[1]==sm.to_string()&&x[2]==case.to_string()&&x[3]==rep.to_string()&&x[4]==name&&x[5]==m.to_string()).unwrap();let expected:Vec<u64>=row[6].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(v.as_slice(),expected.as_slice());}}
counted::reset();let cover=producer::build(&context,&tr);let construction=counted::snapshot();counted::disable();if rep==0{eprintln!("COVER\tp={p}\tsm={sm}\tcase={case}\tpacket={cover:?}");qualify::qualify(&context,&cover);qualify::anchors(&context,&cover);}counted::reset();let ok=verifier::verify(&context,&cover);let checking=counted::snapshot();counted::disable();assert!(ok);assert_eq!(cover.k,k);let conservative=add(&add(&pc,&construction),&checking);let mut candidate=conservative.clone();for(m,v)in &external{let w=candidate.get_mut(m).unwrap();for j in 0..16{w[j]-=v[j]}}
if rep==0{let mut anchors=vec![context.target];anchors.extend(cover.anchor_certificates.iter().map(|x|x.out));let fallback_rows=cover.primitives.iter().filter(|x|!geometry::roots(&c,&anchors[x.a as usize],x.t,&x.points)).count();eprintln!("ROOTS\tp={p}\tsm={sm}\tcase={case}\trows={}\texact_fallbacks={fallback_rows}",cover.primitives.len());}if sm==1{let old:Vec<Vec<&str>>=include_str!("../root-anchor-cover/CONTROL.tsv").lines().skip(1).map(|l|l.split('\t').collect()).collect();for(m,v)in &candidate{let row=old.iter().find(|x|x[0]==p.to_string()&&x[1]==sm.to_string()&&x[2]==case.to_string()&&x[3]==rep.to_string()&&x[4]=="derived_candidate_total"&&x[5]==m.to_string()).unwrap();let expected:Vec<u64>=row[6].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(v[8],expected[8]);}}let signature=(pc.clone(),external.clone(),construction.clone(),checking.clone(),candidate.clone());if let Some(ref old)=first{assert_eq!(old,&signature)}else{first=Some(signature)}for(name,costs)in[("producer_with_native_control",&pc),("native_control",&external),("cover_construction",&construction),("cover_verifier",&checking),("conservative_total",&conservative),("derived_candidate_total",&candidate)]{emit(p,sm,case,rep,name,costs)}for name in["retained_arm0","retained_arm1","derived_candidate_total"]{let mut counts=counted::Counts::new();for row in prior.iter().filter(|x|x[0]==p.to_string()&&x[1]==sm.to_string()&&x[2]==case.to_string()&&x[3]==rep.to_string()&&x[4]==name){let v:Vec<u64>=row[6].split(',').map(|x|x.parse().unwrap()).collect();counts.insert(row[5].parse().unwrap(),v.try_into().unwrap());}emit(p,sm,case,rep,if name=="derived_candidate_total"{"triangular_candidate"}else{name},&counts)}calls+=1;}}}}assert_eq!(calls,24);eprintln!("PASS calls=24 original_targets=12 changed_stream_original_scalar_verified=true source1_REDC_control_exact=true diagnostic_traces_exact=true native_final_control_vectors_exact=true repeats_exact=true all_four_branches_charged=true character_action_calls=0 construction_selfcheck_charged=true no_wall_claim=true common_mutations_rejected_each_verifier=216 anchor_mutations_rejected_new_verifier=96 new_witnesses_verified=true independent_verification=false");}
